 // JUNO Playspace: client-side face actions run immediately and do not consume AI requests.
 const buddySpace=$('#buddySpace'),buddyCharacter=$('#buddyCharacter'),buddyStatus=$('#buddyStatus'),buddyVisual=$('#buddyVisual'),buddyGameLayer=$('#buddyGameLayer'),buddyTarget=$('#buddyTarget'),buddyScore=$('#buddyScore');
