   if(action==='jump'){buddyCharacter.classList.add('jumping');buddyStatusSet('Boing!');setTimeout(()=>buddyCharacter.classList.remove('jumping'),700);return 'JUNO jumped.'}
   if(action==='juggle'){buddyCharacter.classList.add('juggling');buddyStatusSet('Look at me juggle! 🤹');return 'JUNO is juggling.'}
   if(action==='visual'){buddyVisual.classList.remove('hidden');buddyStatusSet('A little interactive orbit visual ✨');return 'Showing an animated visual.'}
