 function runBuddyCommand(command){const s=String(command||'').toLowerCase().replace(/[.!?]/g,' ').replace(/\s+/g,' ').trim();if(/\b(move|go|walk|slide|shift)\b.*\b(right|to the right)\b|\bright\b.*\b(move|go|walk)\b/.test(s))return buddyAction('right');if(/\b(move|go|walk|slide|shift)\b.*\b(left|to the left)\b|\bleft\b.*\b(move|go|walk)\b/.test(s))return buddyAction('left');if(/\b(center|centre|middle|back to normal)\b/.test(s))return buddyAction('center');if(/\b(juggl|toss|balls?)\b/.test(s))return buddyAction('juggle');if(/\b(play|start)\b.*\b(game|catch|star)\b|\b(game|catch the star)\b/.test(s))return buddyAction('game');if(/\b(visual|orbit|show me something|animation|diagram)\b/.test(s))return buddyAction('visual');if(/\b(jump|hop|bounce)\b/.test(s))return buddyAction('jump');if(/\b(blink|close your eyes)\b/.test(s))return buddyAction('blink');if(/\b(wave|hello|hi)\b/.test(s))return buddyAction('wave');if(/\b(smile|happy|cheer up)\b/.test(s))return buddyAction('smile');if(/\b(stop|reset|settle down)\b/.test(s))return buddyAction('stop');buddyStatusSet('Try “move right”, “juggle”, “show a visual”, “jump”, or “play catch”.');return 'I didn’t recognise that action yet. Try move right, juggle, show a visual, jump, or play catch.';}
