 function runBuddyCommandFromSpeech(text){const s=String(text||'').trim();if(!s||s.length>160)return '';const lower=s.toLowerCase();const actionWords=/\b(move|go|walk|slide|shift|juggle|toss|jump|hop|bounce|blink|wave|smile|visual|orbit|animation|play|catch|stop|reset|center|centre|middle)\b/.test(lower);if(!actionWords)return '';if(/\b(what|why|how|who|when|where|explain|tell me|research|search|calculate|write|help)\b/.test(lower)&&!/(\bmove\b|\bgo\b|\bwalk\b|\bjuggle\b|\bjump\b|\bblink\b|\bwave\b|\bsmile\b|\bshow (me )?(a )?(visual|animation|diagram)\b|\b(play|start) (a )?(game|catch)\b|\bstop\b|\breset\b)/.test(lower))return '';return runBuddyCommand(s);}
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!buddySpace.classList.contains('hidden')&&!document.fullscreenElement)closeBuddy();});

 async function init(){try{const d=await api('/api/me');signedIn(d.user);if(d.settings){setSearch(d.settings.allow_web_search!==false,false);$('#themeSelect').disabled=d.settings.allow_theme_choice===false;$('#micButton').disabled=d.settings.allow_voice_input===false;if(d.settings.allow_voice_input===false)$('#micButton').title='Voice input is disabled by the administrator';}if(d.user){try{const pref=await api('/api/preferences');state.notificationPref=!!pref.notifications_enabled;$('#notificationPref').checked=state.notificationPref;$('#displayNameInput').value=pref.display_name||d.user.name;setTheme(pref.theme||'system');}catch{setTheme('system')}await refreshConversations();await loadNotifications();if(!state.conversationId){const c=(await api('/api/conversations')).conversations;if(c.length)await loadChat(c[0].id);else await createChat()}}else refreshConversations()}catch(e){console.warn(e)}if(!state.user){$('#welcome').classList.remove('hidden');$('#profileName').textContent='Guest'} }
 init();
